import torch, triton, time, os
print(torch.__version__, triton.__version__, torch.cuda.get_device_name())
p = torch.cuda.get_device_properties(0); print(p.multi_processor_count, "SMs", p.total_memory>>20, "MB")
import b200probe; print([n for n in dir(b200probe) if not n.startswith('_')])
print(os.environ.get("CUTLASS_DIR"), os.path.exists("/usr/local/cutlass/include/cutlass/gemm/collective/collective_builder.hpp"))
try:
    import cutlass; print("cutlass dsl", cutlass.__version__)
except Exception as e: print("no cutlass dsl", e)

# numerics: harness-style ref vs fused single-rounding vs double-rounding
torch.manual_seed(0)
H=2560
for M in (256, 8192):
    A = torch.randn(M,H,device='cuda').bfloat16(); R = torch.randn(M,H,device='cuda').bfloat16(); W = torch.randn(H,H,device='cuda').bfloat16()
    ref = torch.matmul(A, W.t()) + R
    proj32 = A.float() @ W.float().t()
    ours1 = (proj32 + R.float()).bfloat16()
    ours2 = (proj32.bfloat16().float() + R.float()).bfloat16()
    for name,o in (("single",ours1),("double",ours2)):
        for atol in (0.0093, 0.02):
            ok = (o.float()-ref.float()).abs() <= atol + 0.05*ref.float().abs()
            print(M, name, atol, "mismatch frac %.5f"%(1-ok.float().mean().item()), "maxabs %.3f"%(o.float()-ref.float()).abs().max().item())
    print("ref std", ref.float().std().item())

import torch, b200probe, subprocess
print(subprocess.run("nvidia-smi --query-gpu=clocks.sm,clocks.mem,clocks.max.sm --format=csv",shell=True,capture_output=True,text=True).stdout)
H=2560
W = torch.randn(H,H,device='cuda').bfloat16()
def ref(A,R,W,O): O.copy_(torch.matmul(A,W.t())+R)
def mm(A,R,W,O): torch.matmul(A,W.t(),out=O)
def addmm(A,R,W,O): torch.addmm(R,A,W.t(),out=O)
def lin(A,R,W,O): torch.nn.functional.linear(A,W,out=O) if False else O.copy_(torch.nn.functional.linear(A,W))
for M in (256,512,1024,2048,4096,8192):
    A = torch.randn(M,H,device='cuda').bfloat16(); R = torch.randn(M,H,device='cuda').bfloat16(); O = torch.empty(M,H,device='cuda').bfloat16()
    r = {}
    for name,f in (("mm",mm),("addmm",addmm),("ref",ref)):
        try:
            t = b200probe.harness_time(lambda A,R,W,O: f(A,R,W,O), [A,R,W], [O])
            r[name]=t
        except Exception as e:
            r[name]=str(e)[:80]
    fl = 2*M*H*H
    print(M, {k:(round(v,2) if isinstance(v,float) else v) for k,v in r.items()}, "mm TFLOP/s %.0f"%(fl/r['mm']/1e6) if isinstance(r['mm'],float) else "")

