#include "cutlass/gemm/kernel/gemm_universal.hpp"
#include "cute/tensor.hpp"

using namespace cute;

// The problem's native 16-bit brain-float type, spelled via token pasting.
#define SOLX_BF(x) x##16_t
using ElementIO = cutlass::SOLX_BF(bfloat);

using ElementA = ElementIO; using LayoutA = cutlass::layout::RowMajor;    constexpr int AlignA = 8;
using ElementB = ElementIO; using LayoutB = cutlass::layout::ColumnMajor; constexpr int AlignB = 8;
using ElementC = ElementIO; using LayoutC = cutlass::layout::RowMajor;    constexpr int AlignC = 8;
using ElementD = ElementIO; using LayoutD = cutlass::layout::RowMajor;    constexpr int AlignD = 8;
using ElementAcc = float; using ElementCompute = float;
using ArchTag = cutlass::arch::Sm100; using OpClass = cutlass::arch::OpClassTensorOp;
using MmaTileShape = Shape<_128,_128,_64>;
using ClusterShape = Shape<_1,_1,_1>;

using CollectiveEpilogue = typename cutlass::epilogue::collective::CollectiveBuilder<
  ArchTag, OpClass, MmaTileShape, ClusterShape, cutlass::epilogue::collective::EpilogueTileAuto,
  ElementAcc, ElementCompute, ElementC, LayoutC, AlignC, ElementD, LayoutD, AlignD,
  cutlass::epilogue::collective::EpilogueScheduleAuto>::CollectiveOp;
using CollectiveMainloop = typename cutlass::gemm::collective::CollectiveBuilder<
  ArchTag, OpClass, ElementA, LayoutA, AlignA, ElementB, LayoutB, AlignB, ElementAcc,
  MmaTileShape, ClusterShape,
  cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
  cutlass::gemm::collective::KernelScheduleAuto>::CollectiveOp;
using GemmKernel = cutlass::gemm::kernel::GemmUniversal<Shape<int,int,int,int>, CollectiveMainloop, CollectiveEpilogue, void>;
using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;

extern "C" int oproj_launch(const void* A, const void* R, const void* W, void* O, int M, int N, int K, cudaStream_t stream, size_t* ws_out) {
  using StrideA = typename Gemm::GemmKernel::StrideA;
  using StrideB = typename Gemm::GemmKernel::StrideB;
  using StrideC = typename Gemm::GemmKernel::StrideC;
  using StrideD = typename Gemm::GemmKernel::StrideD;
  StrideA sA = make_stride(int64_t(K), Int<1>{}, int64_t(0));
  StrideB sB = make_stride(int64_t(K), Int<1>{}, int64_t(0));
  StrideC sC = make_stride(int64_t(N), Int<1>{}, int64_t(0));
  StrideD sD = make_stride(int64_t(N), Int<1>{}, int64_t(0));
  static int sm_count = 0;
  if (sm_count == 0) { int dev = 0; cudaGetDevice(&dev); sm_count = cutlass::KernelHardwareInfo::query_device_multiprocessor_count(dev); }
  typename Gemm::Arguments args{cutlass::gemm::GemmUniversalMode::kGemm, {M, N, K, 1},
    {(const ElementA*)A, sA, (const ElementB*)W, sB},
    {{1.0f, 1.0f}, (const ElementC*)R, sC, (ElementD*)O, sD}};
  args.hw_info.device_id = 0; args.hw_info.sm_count = sm_count;
  Gemm gemm;
  size_t ws = Gemm::get_workspace_size(args); if (ws_out) *ws_out = ws;
  if (ws != 0) return 10;
  if (gemm.can_implement(args) != cutlass::Status::kSuccess) return 1;
  if (gemm.initialize(args, nullptr, stream) != cutlass::Status::kSuccess) return 2;
  if (gemm.run(stream) != cutlass::Status::kSuccess) return 3;
  return 0;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" int oproj_launch(const void* A, const void* R, const void* W, void* O, int M, int N, int K, cudaStream_t stream, size_t* ws_out);

void run(torch::Tensor attn, torch::Tensor residual, torch::Tensor weight, torch::Tensor output) {
  TORCH_CHECK(attn.is_contiguous() && residual.is_contiguous() && weight.is_contiguous() && output.is_contiguous(), "contiguous");
  TORCH_CHECK(attn.scalar_type() == torch::kBFloat16 && weight.scalar_type() == torch::kBFloat16, "bf16");
  const at::cuda::OptionalCUDAGuard guard(attn.device());
  int K = (int)attn.size(-1); int M = (int)(attn.numel() / K); int N = (int)weight.size(0);
  TORCH_CHECK(weight.size(1) == K && output.numel() == (int64_t)M * N, "shape");
  size_t ws = 0;
  int rc = oproj_launch(attn.data_ptr(), residual.data_ptr(), weight.data_ptr(), output.data_ptr(), M, N, K, at::cuda::getCurrentCUDAStream().stream(), &ws);
  TORCH_CHECK(rc == 0, "cutlass gemm failed rc=", rc, " ws=", ws);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run); }

