#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cublasLt.h>
#include <cuda_runtime.h>
#include <mutex>
#include <stdexcept>
#include <string>

// D[M,N] = A[M,K] * W[N,K]^T + R[M,N], all bf16 row-major, fp32 accumulate.
// cuBLAS is column-major, so compute D^T[N,M] = op_T(W_col)[N,K] * op_N(A_col)[K,M] + R^T.

#define LT_CHECK(x) do { cublasStatus_t s_ = (x); if (s_ != CUBLAS_STATUS_SUCCESS) \
    throw std::runtime_error(std::string("cublasLt error ") + std::to_string((int)s_) + " at " #x); } while (0)

namespace {
constexpr size_t kWorkspace = 32u << 20;  // 32 MB, the size cuBLAS recommends on Hopper/Blackwell

cublasLtHandle_t get_handle() {
    static cublasLtHandle_t h = nullptr;
    static std::once_flag once;
    std::call_once(once, [] { LT_CHECK(cublasLtCreate(&h)); });
    return h;
}
}  // namespace

void run(torch::Tensor attn_output, torch::Tensor residual, torch::Tensor o_proj_weight, torch::Tensor output) {
    TORCH_CHECK(attn_output.is_cuda() && residual.is_cuda() && o_proj_weight.is_cuda() && output.is_cuda());
