using ElementA = cutlass::bfloat16_t;  using LayoutA = cutlass::layout::RowMajor;     // A[M,K], K contiguous
using ElementB = cutlass::bfloat16_t;  using LayoutB = cutlass::layout::ColumnMajor;  // B[K,N] K contiguous == W[N,K] row-major
using ElementC = cutlass::bfloat16_t;  using LayoutC = cutlass::layout::RowMajor;     // residual
using ElementD = cutlass::bfloat16_t;  using LayoutD = cutlass::layout::RowMajor;     // output
constexpr int Align = 8;
using ElementAcc = float;
using ElementCompute = float;
using ArchTag = cutlass::arch::Sm100;
using OpClass = cutlass::arch::OpClassTensorOp;
using MmaTileShape = Shape<_128, _256, _64>;
using ClusterShape = Shape<_1, _1, _1>;

using CollectiveEpilogue = typename cutlass::epilogue::collective::CollectiveBuilder<
    ArchTag, OpClass, MmaTileShape, ClusterShape, cutlass::epilogue::collective::EpilogueTileAuto,
    ElementAcc, ElementCompute, ElementC, LayoutC, Align, ElementD, LayoutD, Align,
    cutlass::epilogue::TmaWarpSpecialized1Sm>::CollectiveOp;

using CollectiveMainloop = typename cutlass::gemm::collective::CollectiveBuilder<
    ArchTag, OpClass, ElementA, LayoutA, Align, ElementB, LayoutB, Align, ElementAcc,
    MmaTileShape, ClusterShape,
    cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
    cutlass::gemm::KernelTmaWarpSpecialized1SmSm100>::CollectiveOp;

using GemmKernel = cutlass::gemm::kernel::GemmUniversal<Shape<int, int, int, int>, CollectiveMainloop, CollectiveEpilogue, void>;
using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
using StrideA = typename Gemm::GemmKernel::StrideA;
using StrideB = typename Gemm::GemmKernel::StrideB;
using StrideC = typename Gemm::GemmKernel::StrideC;
using StrideD = typename Gemm::GemmKernel::StrideD;

cutlass::KernelHardwareInfo hw_info_once() {
    static cutlass::KernelHardwareInfo hw = [] {
        cutlass::KernelHardwareInfo h;
        h.device_id = 0;
        h.sm_count = cutlass::KernelHardwareInfo::query_device_multiprocessor_count(0);
        return h;
    }();
    return hw;
}
}  // namespace

extern "C" int oproj_launch(const void* A, const void* R, const void* W, void* D,
                             int M, int N, int K, void* ws, size_t ws_bytes, cudaStream_t stream) {
    auto sA = cutlass::make_cute_packed_stride(StrideA{}, {M, K, 1});
    auto sB = cutlass::make_cute_packed_stride(StrideB{}, {N, K, 1});
    auto sC = cutlass::make_cute_packed_stride(StrideC{}, {M, N, 1});
    auto sD = cutlass::make_cute_packed_stride(StrideD{}, {M, N, 1});
    typename Gemm::Arguments args{
        cutlass::gemm::GemmUniversalMode::kGemm,
        {M, N, K, 1},
        {static_cast<const ElementA*>(A), sA, static_cast<const ElementB*>(W), sB},
        {{1.0f, 1.0f}, static_cast<const ElementC*>(R), sC, static_cast<ElementD*>(D), sD},
        hw_info_once()};
    Gemm gemm;
    if (gemm.can_implement(args) != cutlass::Status::kSuccess) return 1;
    if (Gemm::get_workspace_size(args) > ws_bytes) return 2;
    if (gemm.initialize(args, ws, stream) != cutlass::Status::kSuccess) return 3;
    if (gemm.run(stream) != cutlass::Status::kSuccess) return 4;
    return 0;
}

